package net.civeira.phylax.features.access.usermfarecoverycode.domain;

import java.time.LocalDateTime;
import java.time.ZoneId;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.features.access.user.domain.UserReference;

class UserMfaRecoveryCodeChangeSetUnitTest {

  /**
   * @autogenerated CachedGenerator
   */
  @Test
  @DisplayName("Test a entity reference contruction")
  void test_user_mfa_recovery_code_change_set_builder() {
    UserMfaRecoveryCodeChangeSet one =
        new UserMfaRecoveryCodeChangeSet().uid("one").user(UserReference.of("one")).codeHash("one")
            .usedAt(LocalDateTime.of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid"))
                .toOffsetDateTime())
            .createdAt(LocalDateTime.of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid"))
                .toOffsetDateTime())
            .version(1).newUid();
    one.uid("two");
    Assertions.assertEquals("two", one.getUid().get(), "Value must equals to the assigned value");
    one.unset("uid");
    Assertions.assertFalse(one.getUid().isPresent(), "After unset, the valeue must be dissapear");
    Assertions.assertEquals(UserReference.of("one"), one.getUser().get(),
        "Value must equals to the intial value");
    one.user(UserReference.of("two"));
    Assertions.assertEquals(UserReference.of("two"), one.getUser().get(),
        "Value must equals to the assigned value");
    one.unset("user");
    Assertions.assertFalse(one.getUser().isPresent(), "After unset, the valeue must be dissapear");
    Assertions.assertEquals("one", one.getCodeHash().get(),
        "Value must equals to the intial value");
    one.codeHash("two");
    Assertions.assertEquals("two", one.getCodeHash().get(),
        "Value must equals to the assigned value");
    one.unset("codeHash");
    Assertions.assertFalse(one.getCodeHash().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(
        LocalDateTime.of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime(),
        one.getUsedAt().get(), "Value must equals to the intial value");
    one.usedAt(
        LocalDateTime.of(1981, 9, 6, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime());
    Assertions.assertEquals(
        LocalDateTime.of(1981, 9, 6, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime(),
        one.getUsedAt().get(), "Value must equals to the assigned value");
    one.unset("usedAt");
    Assertions.assertFalse(one.getUsedAt().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(
        LocalDateTime.of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime(),
        one.getCreatedAt().get(), "Value must equals to the intial value");
    one.createdAt(
        LocalDateTime.of(1981, 9, 6, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime());
    Assertions.assertEquals(
        LocalDateTime.of(1981, 9, 6, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime(),
        one.getCreatedAt().get(), "Value must equals to the assigned value");
    one.unset("createdAt");
    Assertions.assertFalse(one.getCreatedAt().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(0, one.getVersion().get(), "Value must equals to the intial value");
    one.version(2);
    Assertions.assertEquals(2, one.getVersion().get(), "Value must equals to the assigned value");
    one.unset("version");
    Assertions.assertFalse(one.getVersion().isPresent(),
        "After unset, the valeue must be dissapear");
  }
}
